(async()=>{
  const E=window.__echoes; const s=m=>new Promise(r=>setTimeout(r,m));
  E.cmd('startRun'); await s(150);
  E.cmd('skipToRoom',7); await s(500);
  const v0=E.cmd('runState');
  const stock=v0.shop.stock.map(x=>({node:x.node,rarity:x.rarity,price:x.price,aff:x.affordable,owned:x.owned}));
  const sum3=stock.reduce((a,b)=>a+b.price,0);
  const pairs=[[0,1],[0,2],[1,2]].map(p=>stock[p[0]].price+stock[p[1]].price);
  // buy the two most expensive
  const order=stock.map((x,i)=>({i,p:x.price})).sort((a,b)=>b.p-a.p);
  const b1=E.cmd('shopBuy',order[0].i); await s(200);
  const b2=E.cmd('shopBuy',order[1].i); await s(250);
  const u1=E.runUi();
  const midWallet=E.cmd('runState').wallet;
  // now try the cheapest -> must be denied
  const cheapIdx=order[2].i;
  const cardsBefore=E.runUi().cards.map(c=>({n:c.name,o:c.opacity,f:c.filter}));
  const t0=performance.now();
  const plaqueEl=document.querySelectorAll('.rn-plaque')[cheapIdx];
  const cardEl=document.querySelectorAll('.rn-card')[cheapIdx];
  const xs=[]; const opac=[];
  const b3=E.cmd('shopBuy',cheapIdx);
  await new Promise(res=>{
    const loop=()=>{
      const r=plaqueEl.getBoundingClientRect();
      xs.push(Math.round(r.x*100)/100);
      const st=getComputedStyle(cardEl);
      opac.push([Number(st.opacity), st.filter, st.display, st.visibility]);
      if(performance.now()-t0<420) requestAnimationFrame(loop); else res();
    };
    requestAnimationFrame(loop);
  });
  const u2=E.runUi();
  return { wallet0:v0.wallet, stock, sum3, pairs, b1, b2, b3, midWallet,
    ownedLines:u2.owned, boughtLine: document.querySelector('.rn-bought') ? document.querySelector('.rn-bought').textContent : null,
    plaqueXmin:Math.min(...xs), plaqueXmax:Math.max(...xs), samples:xs.length,
    cardOpacityMin: Math.min(...opac.map(o=>o[0])), filters:[...new Set(opac.map(o=>o[1]))], displays:[...new Set(opac.map(o=>o[2]))], vis:[...new Set(opac.map(o=>o[3]))],
    cardsBefore, cardsAfter:u2.cards.map(c=>({n:c.name,o:c.opacity,f:c.filter,w:c.box.w,h:c.box.h})),
    plaques:u2.plaques, finalWallet:E.cmd('runState').wallet,
    bench: E.cmd('buildView').bench.map(b=>b.node+':'+b.provenance),
    denied: E.events.filter(e=>e.type==='currency_denied').map(e=>({node:e.node,price:e.price,wallet:e.wallet})),
    purchases: E.events.filter(e=>e.type==='shop_purchase').map(e=>({node:e.node,price:e.price,wallet:e.wallet,owned:e.owned})) };
})()
